1	#!/usr/bin/env node
2	
3	import fs from 'fs';
4	import path from 'path';
5	import process from 'process';
6	import { execSync } from 'child_process';
7	import { createRequire } from 'module';
8	
9	import { Command } from 'commander';
10	import inquirer from 'inquirer';
11	
12	import {
13	  Config,
14	  Documents,
15	  Eval,
16	  Finetune,
17	  Providers,
18	  Questionnaire,
19	  Rag,
20	  Scanners
21	} from 'frai-core';
22	
23	const require = createRequire(import.meta.url);
24	const pkg = require('../package.json') as { version?: string; name?: string };
25	
26	type LogLevel = 'info' | 'success' | 'warn' | 'error';
27	type LogMeta = Record<string, unknown> | undefined;
28	
29	const DOC_FILENAMES = ['checklist.md', 'model_card.md', 'risk_file.md'];
30	const LOCAL_ENV_DISPLAY = '.env';
31	const GLOBAL_CONFIG_DISPLAY = '~/.config/frai/config';
32	
33	type ScanResult = ReturnType<typeof Scanners.scanCodebase>;
34	
35	interface GenerateOptions {
36	  scan?: boolean;
37	  ci?: boolean;
38	  key?: string;
39	  global?: boolean;
40	  exportPdf?: boolean;
41	  showConfig?: boolean;
42	}
43	
44	interface ScanOptions {
45	  root?: string;
46	  ci?: boolean;
47	  json?: boolean;
48	  silent?: boolean;
49	}
50	
51	interface EvalOptions {
52	  outputs: string;
53	  references?: string;
54	  report?: string;
55	  format?: 'json' | 'markdown';
56	  threshold?: string[];
57	}
58	
59	interface RagOptions {
60	  input?: string | string[];
61	  output?: string;
62	  chunkSize?: number;
63	  extensions?: string[];
64	}
65	
66	interface FinetuneTemplateOptions {
67	  output?: string;
68	}
69	
70	interface FinetuneValidateOptions {
71	  readiness?: boolean;
72	}
73	
74	const log = {
75	  info(message: string, meta?: LogMeta) {
76	    console.log(formatLog('info', message, meta));
77	  },
78	  success(message: string, meta?: LogMeta) {
79	    console.log(formatLog('success', message, meta));
80	  },
81	  warn(message: string, meta?: LogMeta) {
82	    console.warn(formatLog('warn', message, meta));
83	  },
84	  error(message: string, meta?: LogMeta) {
85	    console.error(formatLog('error', message, meta));
86	  }
87	};
88	
89	function formatLog(level: LogLevel, message: string, meta: LogMeta = undefined) {
90	  const timestamp = new Date().toISOString();
91	  if (!meta || Object.keys(meta).length === 0) {
92	    return `[${timestamp}] ${level.toUpperCase()} ${message}`;
93	  }
94	  let serializedMeta = '';
95	  try {
96	    serializedMeta = JSON.stringify(meta);
97	  } catch (error) {
98	    serializedMeta = String(meta);
99	  }
100	  return `[${timestamp}] ${level.toUpperCase()} ${message} ${serializedMeta}`;
101	}
102	
103	function listDocs() {
104	  const cwd = process.cwd();
105	  const items = DOC_FILENAMES.filter((file) => fs.existsSync(path.join(cwd, file)));
106	  if (!items.length) {
107	    log.info('No documentation files detected in current directory.', { cwd });
108	    return;
109	  }
110	  log.info('Documentation files found:', { files: items });
111	  items.forEach((file) => console.log(`  - ${file}`));
112	}
113	
114	function cleanDocs() {
115	  const cwd = process.cwd();
116	  let removed = 0;
117	  for (const file of DOC_FILENAMES) {
118	    const target = path.join(cwd, file);
119	    if (fs.existsSync(target)) {
120	      fs.unlinkSync(target);
121	      removed += 1;
122	      log.info(`Removed ${file}`);
123	    }
124	  }
125	  if (!removed) {
126	    log.info('No documentation files to remove.');
127	  } else {
128	    log.success('Documentation directory cleaned.', { removed });
129	  }
130	}
131	
132	function exportDocsAsPdf() {
133	  const existing = DOC_FILENAMES.filter((file) => fs.existsSync(file));
134	  if (!existing.length) {
135	    log.warn('No documentation files to export.');
136	    return;
137	  }
138	  try {
139	    execSync(`npx markdown-pdf ${existing.join(' ')}`, { stdio: 'inherit' });
140	    log.success('PDF export complete.');
141	  } catch (error) {
142	    log.error('Failed to export documentation as PDF.', {
143	      error: error instanceof Error ? error.message : String(error)
144	    });
145	  }
146	}
147	
148	function showConfigStatus() {
149	  const local = {
150	    exists: Config.hasLocalApiKey(),
151	    value: Config.getLocalApiKey()
152	  };
153	  const global = {
154	    exists: Config.hasGlobalApiKey(),
155	    value: Config.getGlobalApiKey()
156	  };
157	
158	  const status = {
159	    local: {
160	      configured: local.exists,
161	      location: LOCAL_ENV_DISPLAY
162	    },
163	    global: {
164	      configured: global.exists,
165	      location: GLOBAL_CONFIG_DISPLAY
166	    }
167	  };
168	
169	  log.info('API key configuration status', status);
170	  if (local.exists) {
171	    log.info('Local API key detected (masked).');
172	  }
173	  if (global.exists) {
174	    log.info('Global API key detected (masked).');
175	  }
176	  if (!local.exists && !global.exists) {
177	    log.warn('No OpenAI API key configured. Some AI powered features will be unavailable.');
178	  }
179	}
180	
181	async function configureApiKeyIfProvided(key?: string, scopeGlobal = false) {
182	  if (!key) return;
183	  if (scopeGlobal) {
184	    Config.setGlobalApiKey(key);
185	    log.success('Stored OpenAI API key in global configuration.', { location: GLOBAL_CONFIG_DISPLAY });
186	  } else {
187	    Config.setLocalApiKey(key);
188	    log.success('Stored OpenAI API key in local configuration.', { location: LOCAL_ENV_DISPLAY });
189	  }
190	}
191	
192	function resolveConfiguredApiKey() {
193	  const local = Config.getLocalApiKey();
194	  if (local) return local;
195	  return Config.getGlobalApiKey();
196	}
197	
198	async function promptForApiKey(scopeGlobal?: boolean) {
199	  const answers = await inquirer.prompt<{ apiKey: string }>([
200	    {
201	      type: 'password',
202	      name: 'apiKey',
203	      message: `Enter your OpenAI API key (${scopeGlobal ? 'global' : 'local'} storage):`,
204	      mask: '*',
205	      validate: (value) => Boolean(value?.trim()) || 'API key is required.'
206	    }
207	  ]);
208	  await configureApiKeyIfProvided(answers.apiKey, scopeGlobal);
209	  return answers.apiKey;
210	}
211	
212	function summarizeScanResult(scan: ScanResult | null) {
213	  if (!scan) return '';
214	  const libraryEntries = (Object.entries(scan.aiLibraryMatches ?? {}) as Array<[string, number]>).sort(
215	    (a, b) => b[1] - a[1]
216	  );
217	  const functionEntries = (Object.entries(scan.aiFunctionMatches ?? {}) as Array<[string, number]>).sort(
218	    (a, b) => b[1] - a[1]
219	  );
220	  const libraries = libraryEntries.slice(0, 5).map(([name, count]) => `${name} (${count})`).join(', ');
221	  const functions = functionEntries.slice(0, 5).map(([name, count]) => `${name} (${count})`).join(', ');
222	
223	  return [
224	    `Detected ${scan.aiFiles.length} AI related files out of ${scan.totalFiles} scanned.`,
225	    libraries ? `Top libraries: ${libraries}` : 'No AI libraries detected.',
226	    functions ? `Top functions: ${functions}` : 'No AI-specific functions detected.'
227	  ].join('\n');
228	}
229	
230	function runScanCommand({ root = process.cwd(), ci = false, json = false, silent = false }: ScanOptions) {
231	  const result = Scanners.scanCodebase({ root });
232	
233	  if (json) {
234	    console.log(JSON.stringify(result, null, 2));
235	    return result;
236	  }
237	
238	  if (!silent) {
239	    log.info('Scan completed.', {
240	      totalFiles: result.totalFiles,
241	      aiFiles: result.aiFiles.length
242	    });
243	    if (result.aiFiles.length) {
244	      console.log('AI-related files:');
245	      result.aiFiles.forEach((file) => console.log(`  - ${path.relative(root, file)}`));
246	    }
247	    if (!result.aiFiles.length) {
248	      log.info('No AI indicators detected in scope.');
249	    }
250	    if (ci) {
251	      log.info('CI mode: exiting after scan.');
252	    }
253	  }
254	
255	  return result;
256	}
257	
258	type FetchLike = (input: unknown, init?: unknown) => Promise<unknown>;
259	
260	let cachedFetch: FetchLike | null = null;
261	
262	async function resolveFetchImplementation(): Promise<FetchLike> {
263	  if (typeof (globalThis as { fetch?: FetchLike }).fetch === 'function') {
264	    return (globalThis as { fetch: FetchLike }).fetch.bind(globalThis);
265	  }
266	  if (cachedFetch) return cachedFetch;
267	  const mod = await import('node-fetch');
268	  cachedFetch = (mod.default ?? mod) as FetchLike;
269	  return cachedFetch;
270	}
271	
272	async function generateAITips(answers: Awaited<ReturnType<typeof Questionnaire.runQuestionnaire>>, apiKey: string | null, scan: ScanResult | null) {
273	  if (!apiKey) {
274	    return null;
275	  }
276	  try {
277	    const fetchImpl = await resolveFetchImplementation();
278	    const provider = (Providers.createProvider as unknown as (config: unknown) => any)({
279	      apiKey,
280	      fetch: fetchImpl
281	    });
282	    const context = Documents.buildContextForAITips(answers);
283	    const scanSummary = summarizeScanResult(scan);
284	    const prompt = [
285	      'You are an expert in responsible AI implementation.',
286	      'Provide three actionable recommendations for each documentation artefact (checklist, model card, risk file).',
287	      'Ground the advice in the following feature context and scan summary.'
288	    ].join(' ');
289	
290	    const userContent = [
291	      'AI Feature Context:',
292	      context,
293	      '',
294	      'Scan Summary:',
295	      scanSummary || 'No automated scan results were available.'
296	    ].join('\n');
297	
298	    const response = await provider.chatCompletion({
299	      messages: [
300	        {
301	          role: 'system',
302	          content: prompt
303	        },
304	        {
305	          role: 'user',
306	          content: userContent
307	        }
308	      ],
309	      temperature: 0.3,
310	      maxTokens: 800
311	    });
312	
313	    if (!response?.content) return null;
314	    return String(response.content).trim();
315	  } catch (error) {
316	    log.warn('Unable to generate AI assistance tips. Continuing without them.', {
317	      error: error instanceof Error ? error.message : String(error)
318	    });
319	    return null;
320	  }
321	}
322	
323	function extractTips(markdown: string | null) {
324	  const sections = {
325	    checklist: '',
326	    modelCard: '',
327	    riskFile: ''
328	  };
329	
330	  if (!markdown) {
331	    return sections;
332	  }
333	
334	  type SectionKey = keyof typeof sections;
335	  const markers: Record<string, SectionKey> = {
336	    'checklist tips': 'checklist',
337	    'model card tips': 'modelCard',
338	    'risk file tips': 'riskFile'
339	  };
340	
341	  let current: SectionKey | null = null;
342	  const lines = markdown.split('\n');
343	  for (const line of lines) {
344	    const normalized = line.trim().toLowerCase();
345	    const key = normalized.replace(/[:\s]+$/u, '');
346	    const sectionKey = markers[key];
347	    if (sectionKey) {
348	      current = sectionKey;
349	      sections[sectionKey] = '';
350	      continue;
351	    }
352	    if (current) {
353	      sections[current] = `${sections[current]}${line}\n`;
354	    }
355	  }
356	
357	  for (const key of Object.keys(sections) as SectionKey[]) {
358	    sections[key] = sections[key].trim();
359	  }
360	
361	  return sections;
362	}
363	
364	async function runGenerateFlow(options: GenerateOptions) {
365	  await configureApiKeyIfProvided(options.key, options.global);
366	  const apiKey = resolveConfiguredApiKey();
367	
368	  if (options.showConfig) {
369	    showConfigStatus();
370	  }
371	
372	  let scanResult: ScanResult | null = null;
373	  if (options.scan || options.ci) {
374	    scanResult = runScanCommand({ ci: options.ci, silent: false });
375	    if ((!scanResult || scanResult.aiFiles.length === 0) && options.ci) {
376	      log.info('CI mode completed with no AI code detected. Exiting without generating documentation.');
377	      return;
378	    }
379	    if (scanResult && scanResult.aiFiles.length === 0 && !options.ci) {
380	      const { proceed } = await inquirer.prompt<{ proceed: boolean }>([
381	        {
382	          type: 'confirm',
383	          name: 'proceed',
384	          message: 'No AI indicators detected. Generate documentation manually?',
385	          default: true
386	        }
387	      ]);
388	      if (!proceed) {
389	        log.info('Documentation generation cancelled.');
390	        return;
391	      }
392	    }
393	  }
394	
395	  const answers = await Questionnaire.runQuestionnaire({ prompt: (questions) => inquirer.prompt(questions) });
396	  log.info('Generating documentation artefacts...');
397	  const aiTips = await generateAITips(answers, apiKey ?? null, scanResult);
398	  const tipSections = extractTips(aiTips);
399	
400	  const { checklist, modelCard, riskFile } = Documents.generateDocuments({
