477	function parseThresholds(thresholdStrings?: string[]) {
478	  if (!thresholdStrings || thresholdStrings.length === 0) {
479	    return {};
480	  }
481	
482	  const thresholds: Record<string, number> = {};
483	  const validMetrics = ['exact_match', 'toxicity', 'length_variance'];
484	
485	  for (const thresholdStr of thresholdStrings) {
486	    const parts = thresholdStr.split('=');
487	    if (parts.length !== 2) {
488	      log.error(`Invalid threshold format: ${thresholdStr}. Expected format: <metric>=<number>`);
489	      console.error(`Valid metrics: ${validMetrics.join(', ')}`);
490	      process.exit(2);
491	    }
492	
493	    const metricId = parts[0].trim();
494	    const minStr = parts[1].trim();
495	
496	    if (!validMetrics.includes(metricId)) {
497	      log.error(`Unknown metric: ${metricId}`);
498	      console.error(`Valid metrics: ${validMetrics.join(', ')}`);
499	      process.exit(2);
500	    }
501	
502	    const min = Number.parseFloat(minStr);
503	    if (Number.isNaN(min) || min < 0 || min > 1) {
504	      log.error(`Invalid threshold value for ${metricId}: ${minStr}. Must be a number between 0 and 1.`);
505	      process.exit(2);
506	    }
507	
508	    thresholds[metricId] = min;
509	  }
510	
511	  return thresholds;
512	}
