      path: resolvedPath,
      failed: failedThresholds.map((t: any) => `${t.metric} (min: ${t.min}, score: ${t.score})`)
    });
    process.exit(1);
  }

  log.success('Evaluation report generated.', { path: resolvedPath });
}

