    reportPath: options.report
  });

  if (report.passed === false) {
    const failedThresholds = report.thresholds.filter((t: any) => !t.passed);
    log.error('Evaluation report generated but thresholds failed.', {
      path: resolvedPath,
      failed: failedThresholds.map((t: any) => `${t.metric} (min: ${t.min}, score: ${t.score})`)
    });
    process.exit(1);
  }

  log.success('Evaluation report generated.', { path: resolvedPath });
}

