export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
} = {}) {
  const validatedThresholds = typeof thresholds === 'object' && thresholds !== null ? thresholds : {};

  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdResults = [];
  let allPassed = true;

  for (const [metricId, minScore] of Object.entries(validatedThresholds)) {
    const min = typeof minScore === 'number' ? minScore : Number(minScore);
    if (Number.isNaN(min) || min < 0 || min > 1) {
      throw new Error(`Invalid threshold value for ${metricId}: ${minScore}. Must be a number between 0 and 1.`);
    }
    const metric = evaluations.find((m) => m.id === metricId);
    const metricScore = metric?.score ?? null;
    const passed = metricScore !== null && metricScore >= min;
    if (!passed) {
      allPassed = false;
    }
    thresholdResults.push({
      metric: metricId,
      min,
      score: metricScore,
      passed
    });
  }
